import type { ManualBuild } from "@/lib/api";

export type CrossListingChannel =
  | "ebay_uk"
  | "flipflop_shop"
  | "onbuy"
  | "amazon"
  | "facebook_catalog"
  | "vinted";

export type CrossListingStatus =
  | "draft"
  | "queued"
  | "validating"
  | "ready"
  | "publishing"
  | "published"
  | "updated"
  | "manual_action_required"
  | "failed"
  | "cancelled";

export type SourcePlatform = "ebay_uk" | "flipflop_shop";

export interface CanonicalListing {
  productId: string;
  sku: string;
  title: string;
  description: string;
  bulletPoints: string[];
  faqs: Array<{ question: string; answer: string }>;
  price: number | null;
  currency: "GBP";
  quantity: number;
  condition: string;
  images: Array<{ url: string; alt: string; order: number }>;
  specifications: Record<string, string>;
  warranty: string;
  shipping: string;
  /** Cross-listing safety policy. This must never allow collection/pickup. */
  deliveryMode: "delivery_only";
  collectionAllowed: false;
  pickupAllowed: false;
  returnPolicy: string;
  sourceBuildId: number;
}

export interface CrossListingSource {
  id: string;
  source: SourcePlatform;
  /** Destination channel for synthetic rows backed by channel_listings. */
  channel?: CrossListingChannel;
  externalId: string;
  canonicalProductId: string;
  buildId: number;
  title: string;
  imageUrl: string | null;
  price: number | null;
  currency: "GBP";
  quantity: number;
  condition: string;
  status: "live" | "draft" | "sold" | "ended" | "unavailable" | "failed";
  url: string | null;
  updatedAt: string;
  error?: string | null;
  listing: CanonicalListing;
}

export interface ChannelCapability {
  channel: CrossListingChannel;
  label: string;
  /** Maximum number of listing images, including the main image. Null means no channel limit is configured. */
  maxImages: number | null;
  mode: "api" | "manual" | "not_connected" | "requires_approval";
  connected: boolean;
  canPublish: boolean;
  canUpdate: boolean;
  canEnd: boolean;
  note: string;
  officialReference: string;
}

export interface CrossListingJobResult {
  channel: CrossListingChannel;
  buildId: number;
  status: CrossListingStatus;
  message: string;
  externalId?: string;
  url?: string;
}

export interface CrossListingSourceResponse {
  items: CrossListingSource[];
  refreshedAt: string;
  warnings: string[];
}

const sourceStatus = (
  build: ManualBuild,
  source: SourcePlatform
): CrossListingSource["status"] => {
  if (build.status === "sold") return "sold";
  if (source === "ebay_uk") {
    if (build.ebay_listing_status === "active" || build.ebay_live)
      return "live";
    if (build.ebay_listing_status === "draft") return "draft";
    if (build.ebay_listing_status === "ended") return "ended";
    return "unavailable";
  }
  if (build.status === "in_progress" && !build.storefront_product_id)
    return "draft";
  return build.storefront_product_id
    ? build.storefront_live === false
      ? "ended"
      : "live"
    : "unavailable";
};

function specifications(build: ManualBuild): Record<string, string> {
  const result: Record<string, string> = {};
  for (const component of build.components ?? []) {
    if (component.name) result[component.slot] = component.name;
  }
  return result;
}

export function canonicalFromBuild(build: ManualBuild): CanonicalListing {
  const photos = (build.photos ?? [])
    .filter((photo) => photo.kind === "photo")
    .map((photo, index) => ({
      url: photo.url,
      alt: `${build.name} product photo ${index + 1}`,
      order: index,
    }));
  return {
    productId: String(build.id),
    sku: `FF-BUILD-${build.id}`,
    title: build.generated_title || build.name,
    description:
      build.generated_description || "Listing copy has not been generated yet.",
    bulletPoints: Object.values(build.generated_aspects ?? {})
      .flat()
      .slice(0, 8),
    faqs: [],
    // Cross-listing uses the canonical build valuation. ebay_price may be an
    // old marketplace-specific anchor (including an offer ceiling), which can
    // be substantially higher than the saved canonical price.
    price: build.last_evaluation?.mid ?? build.ebay_price ?? null,
    currency: "GBP",
    quantity: build.status === "sold" ? 0 : 1,
    condition: build.ebay_condition || "Used",
    images: photos,
    specifications: specifications(build),
    warranty:
      "See the saved build warranty and returns policy before publishing.",
    shipping: build.shipping_method || "Configure shipping before publishing.",
    deliveryMode: "delivery_only",
    collectionAllowed: false,
    pickupAllowed: false,
    returnPolicy: `${build.return_days ?? 30} day returns`,
    sourceBuildId: build.id,
  };
}

export function sourcesFromBuild(build: ManualBuild): CrossListingSource[] {
  const listing = canonicalFromBuild(build);
  const items: CrossListingSource[] = [];
  if (build.ebay_listing_id || build.ebay_listing_status !== "never_listed") {
    items.push({
      id: `ebay_uk:${build.id}`,
      source: "ebay_uk",
      externalId: build.ebay_listing_id || "not-created",
      canonicalProductId: String(build.id),
      buildId: build.id,
      title: listing.title,
      imageUrl: listing.images[0]?.url ?? build.hero_photo_url,
      price: listing.price,
      currency: "GBP",
      quantity: listing.quantity,
      condition: listing.condition,
      status: sourceStatus(build, "ebay_uk"),
      url: build.ebay_listing_url,
      updatedAt: build.updated_at,
      listing,
    });
  }
  // A built canonical listing must be visible in Cross-listing even before it
  // has a first channel listing. Represent that pending storefront identity
  // without inventing a product ID or URL.
  // Keep newly-created builds visible so they can be reviewed/prepared before
  // they are marked built. The publish endpoints still enforce the lifecycle
  // requirement that a build must be built before it can go live.
  if (
    build.storefront_product_id ||
    ["in_progress", "built", "listed", "sold"].includes(build.status)
  ) {
    items.push({
      id: `flipflop_shop:${build.id}`,
      source: "flipflop_shop",
      externalId: build.storefront_product_id
        ? String(build.storefront_product_id)
        : "not-created",
      canonicalProductId: String(build.id),
      buildId: build.id,
      title: listing.title,
      imageUrl: listing.images[0]?.url ?? build.hero_photo_url,
      price: listing.price,
      currency: "GBP",
      quantity: listing.quantity,
      condition: listing.condition,
      status: sourceStatus(build, "flipflop_shop"),
      url: null,
      updatedAt: build.updated_at,
      listing,
    });
  }
  return items;
}

export function capabilities(
  ebayConnected: boolean,
  amazonConnected = false,
  amazonMessage?: string
): ChannelCapability[] {
  return [
    {
      channel: "ebay_uk",
      label: "eBay UK",
      maxImages: 24,
      mode: ebayConnected ? "api" : "not_connected",
      connected: ebayConnected,
      canPublish: ebayConnected,
      canUpdate: ebayConnected,
      canEnd: ebayConnected,
      note: ebayConnected
        ? "Uses the existing seller OAuth and manual-build eBay operations."
        : "Connect the existing eBay seller account in Settings.",
      officialReference:
        "https://developer.ebay.com/api-docs/sell/inventory/overview.html",
    },
    {
      channel: "flipflop_shop",
      label: "FlipFlop.shop",
      maxImages: null,
      mode: "api",
      connected: true,
      canPublish: true,
      canUpdate: true,
      canEnd: false,
      note: "Reuses the canonical storefront product; duplicate products are not created here.",
      officialReference: "Internal storefront API",
    },
    {
      channel: "onbuy",
      label: "OnBuy",
      maxImages: 12,
      mode: "manual",
      connected: false,
      canPublish: false,
      canUpdate: false,
      canEnd: false,
      note: "Seller API/feed onboarding is not configured in this app. Manual listing pack only.",
      officialReference: "https://www.onbuy.com/gb/sell/",
    },
    {
      channel: "amazon",
      label: "Amazon",
      maxImages: 10,
      mode: amazonConnected ? "api" : "requires_approval",
      connected: amazonConnected,
      canPublish: amazonConnected,
      canUpdate: amazonConnected,
      canEnd: false,
      note: amazonConnected
        ? "Seller-authorized SP-API connection. Amazon may still return category, GTIN or product-type requirements for review."
        : amazonMessage ||
          "Add the Amazon SP-API variables to the API service and authorize the seller account.",
      officialReference:
        "https://developer-docs.amazon.com/sp-api/docs/manage-product-listings-guide",
    },
    {
      channel: "facebook_catalog",
      label: "Facebook catalog",
      maxImages: 10,
      mode: "manual",
      connected: false,
      canPublish: false,
      canUpdate: false,
      canEnd: false,
      note: "Catalog/feed route must be configured; personal Marketplace automation is not supported.",
      officialReference: "https://www.facebook.com/business/help/",
    },
    {
      channel: "vinted",
      label: "Vinted",
      maxImages: 20,
      mode: "manual",
      connected: false,
      canPublish: false,
      canUpdate: false,
      canEnd: false,
      note: "No approved seller integration is configured. Manual-assist export only; no consumer-account automation.",
      officialReference: "https://www.vinted.co.uk/help",
    },
  ];
}
